def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[()+*/,:=<>-]")
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "NEG": 4,
        ":": 5,
    }

    def parse(content):
        if not content.startswith("="):
            return ("num", int(content))

        nodes = []
        operators = []
        argument_counts = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "NEG":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                if op == ":":
                    nodes.append(("range", left[1], right[1]))
                else:
                    nodes.append(("binary", op, left, right))

        for token in token_pattern.findall(content[1:]):
            if token[0].isdigit():
                nodes.append(("num", int(token)))
                expect_operand = False
            elif token in functions:
                operators.append(token)
                expect_operand = True
            elif token[0].isalpha():
                nodes.append(("ref", token))
                expect_operand = False
            elif token == "(":
                operators.append("(")
                argument_counts.append(1)
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()
                if operators and operators[-1] in functions:
                    function = operators.pop()
                    args = nodes[-count:]
                    del nodes[-count:]
                    nodes.append(("call", function, args))
                expect_operand = False
            else:
                op = "NEG" if token == "-" and expect_operand else token
                while operators and operators[-1] in precedence:
                    top = operators[-1]
                    if precedence[top] < precedence[op]:
                        break
                    if precedence[top] == precedence[op] and op == "NEG":
                        break
                    reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def argument_nodes(args):
        for node in args:
            if node[0] != "range":
                yield node
                continue

            first, last = node[1], node[2]
            col_start, col_end = sorted((ord(first[0]), ord(last[0])))
            row_start, row_end = sorted((int(first[1:]), int(last[1:])))
            for row in range(row_start, row_end + 1):
                for col in range(col_start, col_end + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("ref", name)

    def calculate(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right

    values = {}
    active = set()
    result = 0

    # Both expression evaluation and cell traversal use this explicit stack.
    for root in cells:
        if root in values:
            continue

        stack = [("cell", root)]
        while stack:
            task = stack.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in values:
                    result = values[name]
                elif name not in cells:
                    result = 0
                elif name in active:
                    result = "#CYCLE!"
                else:
                    active.add(name)
                    node = parse(cells[name])
                    stack.append(("finish_cell", name))
                    stack.append(("eval", node))

            elif kind == "finish_cell":
                name = task[1]
                values[name] = result
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "num":
                    result = node[1]
                elif node_kind == "ref":
                    stack.append(("cell", node[1]))
                elif node_kind == "neg":
                    stack.append(("negate",))
                    stack.append(("eval", node[1]))
                elif node_kind == "binary":
                    stack.append(("after_left", node[1], node[3]))
                    stack.append(("eval", node[2]))
                elif node_kind == "call":
                    function, args = node[1], node[2]
                    if function == "IF":
                        stack.append(("choose", args[1], args[2]))
                        stack.append(("eval", args[0]))
                    else:
                        stack.append((
                            "aggregate_next",
                            function,
                            argument_nodes(args),
                            None,
                        ))

            elif kind == "negate":
                if not isinstance(result, str):
                    result = -result

            elif kind == "after_left":
                if not isinstance(result, str):
                    stack.append(("after_right", task[1], result))
                    stack.append(("eval", task[2]))

            elif kind == "after_right":
                if not isinstance(result, str):
                    result = calculate(task[1], task[2], result)

            elif kind == "choose":
                if not isinstance(result, str):
                    stack.append(("eval", task[1] if result else task[2]))

            elif kind == "aggregate_next":
                function, iterator, accumulated = task[1:]
                node = next(iterator, None)
                if node is None:
                    result = 0 if accumulated is None else accumulated
                else:
                    stack.append((
                        "aggregate_result", function, iterator, accumulated
                    ))
                    stack.append(("eval", node))

            elif kind == "aggregate_result":
                if isinstance(result, str):
                    continue

                function, iterator, accumulated = task[1:]
                if accumulated is None:
                    accumulated = result
                elif function == "SUM":
                    accumulated += result
                elif function == "MIN":
                    accumulated = min(accumulated, result)
                else:
                    accumulated = max(accumulated, result)

                stack.append((
                    "aggregate_next", function, iterator, accumulated
                ))

    return {name: values[name] for name in cells}
